    cur.setdefault(str(key),[]).append((tid,sha,st))
allt={}
for tid,key,sha,st,sup in q("select translation_id, source_row_key, source_sha256, status, superseded_by_translation_id from translations where source_table='source_value_extractions' and source_column='claim_text'"):
    allt.setdefault(str(key),[]).append((tid,st,sup))
cnt=Counter(); miss=[]
for xid,ref,p,lang,ld,txt in q("select x.extraction_id,x.ref_id,x.parameter_id,e.language,e.lang_detected,x.claim_text from source_value_extractions x join evidence_sources e using(ref_id) where x.retired_at is null"):
    l = lang or ld
    if l in (None,'en','eng'): 
        cnt[('en/none',l)]+=1; continue
    h=hashlib.sha256((txt or '').encode()).hexdigest()
    t=cur.get(str(xid),[])
    ok=[x for x in t if x[2]=='reviewed']
    shaok=[x for x in ok if x[1]==h]
    key=(l, bool(ok), bool(shaok))
    cnt[key]+=1
    if not shaok: miss.append((xid,ref,p,l,bool(ok),allt.get(str(xid)), (txt or '')[:60]))
for k,v in sorted(cnt.items(), key=str): print(k,v)
for m in miss: print(m)
print(q("select source_row_key from v_translations_current limit 3"))
